import type { ApiError } from "@kisi-workflow/shared";
import type { FastifyReply } from "fastify";

export function statusCodeForApiError(error: ApiError): number {
  switch (error.error) {
    case "validation_error":
      return 400;
    case "unauthorized":
      return 401;
    case "workflow_disabled":
      return 403;
    case "not_found":
      return 404;
    case "payload_too_large":
      return 413;
    case "internal_error":
      return 500;
  }
}

export function sendApiError(reply: FastifyReply, error: ApiError): FastifyReply {
  return reply.status(statusCodeForApiError(error)).send(error);
}

import { randomBytes } from "node:crypto";

import { TRIGGER_TOKEN_LENGTH } from "@kisi-workflow/shared";

export function generateTriggerToken(): string {
  return randomBytes(TRIGGER_TOKEN_LENGTH / 2).toString("hex");
}

export function triggerPathFor(token: string): string {
  return `/t/${token}`;
}

export function triggerUrlFor(publicUrl: string, triggerPath: string): string {
  return `${publicUrl.replace(/\/+$/, "")}${triggerPath}`;
}

export class UniqueTriggerTokenError extends Error {
  constructor() {
    super("trigger token already exists");
    this.name = "UniqueTriggerTokenError";
  }
}

import type { Workflow, WorkflowPatch, WorkflowPut, WorkflowStep } from "@kisi-workflow/shared";

export type PersistedWorkflow = Omit<Workflow, "triggerUrl">;

export type WorkflowCreateRecord = {
  name: string;
  enabled: boolean;
  steps: WorkflowStep[];
  triggerToken: string;
  triggerPath: string;
};

export interface WorkflowRepository {
  list(): Promise<PersistedWorkflow[]>;
  getById(id: string): Promise<PersistedWorkflow | null>;
  create(input: WorkflowCreateRecord): Promise<PersistedWorkflow>;
  update(id: string, patch: WorkflowPatch): Promise<PersistedWorkflow | null>;
  replace(id: string, put: WorkflowPut): Promise<PersistedWorkflow | null>;
  deleteById(id: string): Promise<boolean>;
}

import { randomUUID } from "node:crypto";

import type { WorkflowPatch, WorkflowPut } from "@kisi-workflow/shared";

import { UniqueTriggerTokenError } from "./errors.js";
import type {
  PersistedWorkflow,
  WorkflowCreateRecord,
  WorkflowRepository,
} from "./workflow-repository.js";

export class InMemoryWorkflowRepository implements WorkflowRepository {
  private readonly workflows = new Map<string, PersistedWorkflow>();

  async list(): Promise<PersistedWorkflow[]> {
    return [...this.workflows.values()].sort((left, right) =>
      left.createdAt < right.createdAt ? 1 : -1,
    );
  }

  async getById(id: string): Promise<PersistedWorkflow | null> {
    return this.workflows.get(id) ?? null;
  }

  async create(input: WorkflowCreateRecord): Promise<PersistedWorkflow> {
    for (const existing of this.workflows.values()) {
      if (
        existing.triggerToken === input.triggerToken ||
        existing.triggerPath === input.triggerPath
      ) {
        throw new UniqueTriggerTokenError();
      }
    }

    const now = new Date().toISOString();
    const record: PersistedWorkflow = {
      id: randomUUID(),
      name: input.name,
      enabled: input.enabled,
      triggerToken: input.triggerToken,
      triggerPath: input.triggerPath,
      steps: input.steps,
      createdAt: now,
      updatedAt: now,
    };
    this.workflows.set(record.id, record);
    return record;
  }

  async update(id: string, patch: WorkflowPatch): Promise<PersistedWorkflow | null> {
    const existing = this.workflows.get(id);
    if (!existing) {
      return null;
    }

    const updated: PersistedWorkflow = {
      ...existing,
      name: patch.name ?? existing.name,
      enabled: patch.enabled ?? existing.enabled,
      steps: patch.steps ?? existing.steps,
      updatedAt: new Date().toISOString(),
    };
    this.workflows.set(id, updated);
    return updated;
  }

  async replace(id: string, put: WorkflowPut): Promise<PersistedWorkflow | null> {
    const existing = this.workflows.get(id);
    if (!existing) {
      return null;
    }

    const updated: PersistedWorkflow = {
      ...existing,
      name: put.name,
      enabled: put.enabled,
      steps: put.steps,
      updatedAt: new Date().toISOString(),
    };
    this.workflows.set(id, updated);
    return updated;
  }

  async deleteById(id: string): Promise<boolean> {
    return this.workflows.delete(id);
  }
}

import { Prisma, PrismaClient } from "@prisma/client";
import { WorkflowStepsSchema } from "@kisi-workflow/shared";
import type { WorkflowPatch, WorkflowPut } from "@kisi-workflow/shared";

import { UniqueTriggerTokenError } from "./errors.js";
import type {
  PersistedWorkflow,
  WorkflowCreateRecord,
  WorkflowRepository,
} from "./workflow-repository.js";

function toInputJson(value: unknown): Prisma.InputJsonValue {
  const serialized: unknown = JSON.parse(JSON.stringify(value));
  return serialized as Prisma.InputJsonValue;
}

function isRecordNotFound(error: unknown): boolean {
  return error instanceof Prisma.PrismaClientKnownRequestError && error.code === "P2025";
}

function isUniqueConflict(error: unknown): boolean {
  return error instanceof Prisma.PrismaClientKnownRequestError && error.code === "P2002";
}

function toPersisted(row: {
  id: string;
  name: string;
  enabled: boolean;
  triggerToken: string;
  triggerPath: string;
  steps: Prisma.JsonValue;
  createdAt: Date;
  updatedAt: Date;
}): PersistedWorkflow {
  return {
    id: row.id,
    name: row.name,
    enabled: row.enabled,
    triggerToken: row.triggerToken,
    triggerPath: row.triggerPath,
    steps: WorkflowStepsSchema.parse(row.steps),
    createdAt: row.createdAt.toISOString(),
    updatedAt: row.updatedAt.toISOString(),
  };
}

export class PrismaWorkflowRepository implements WorkflowRepository {
  constructor(private readonly prisma: PrismaClient) {}

  async list(): Promise<PersistedWorkflow[]> {
    const rows = await this.prisma.workflow.findMany({
      orderBy: { createdAt: "desc" },
    });
    return rows.map(toPersisted);
  }

  async getById(id: string): Promise<PersistedWorkflow | null> {
    const row = await this.prisma.workflow.findUnique({ where: { id } });
    return row ? toPersisted(row) : null;
  }

  async create(input: WorkflowCreateRecord): Promise<PersistedWorkflow> {
    try {
      const row = await this.prisma.workflow.create({
        data: {
          name: input.name,
          enabled: input.enabled,
          triggerToken: input.triggerToken,
          triggerPath: input.triggerPath,
          steps: toInputJson(input.steps),
        },
      });
      return toPersisted(row);
    } catch (error) {
      if (isUniqueConflict(error)) {
        throw new UniqueTriggerTokenError();
      }
      throw error;
    }
  }

  async update(id: string, patch: WorkflowPatch): Promise<PersistedWorkflow | null> {
    try {
      const row = await this.prisma.workflow.update({
        where: { id },
        data: {
          ...(patch.name !== undefined ? { name: patch.name } : {}),
          ...(patch.enabled !== undefined ? { enabled: patch.enabled } : {}),
          ...(patch.steps !== undefined ? { steps: toInputJson(patch.steps) } : {}),
        },
      });
      return toPersisted(row);
    } catch (error) {
      if (isRecordNotFound(error)) {
        return null;
      }
      throw error;
    }
  }

  async replace(id: string, put: WorkflowPut): Promise<PersistedWorkflow | null> {
    try {
      const row = await this.prisma.workflow.update({
        where: { id },
        data: {
          name: put.name,
          enabled: put.enabled,
          steps: toInputJson(put.steps),
        },
      });
      return toPersisted(row);
    } catch (error) {
      if (isRecordNotFound(error)) {
        return null;
      }
      throw error;
    }
  }

  async deleteById(id: string): Promise<boolean> {
    try {
      await this.prisma.workflow.delete({ where: { id } });
      return true;
    } catch (error) {
      if (isRecordNotFound(error)) {
        return false;
      }
      throw error;
    }
  }
}

import { z } from "zod";

export const CRUD_BODY_LIMIT_BYTES = 256 * 1024;
export const DEFAULT_PORT = 3000;

const EnvSchema = z.object({
  DATABASE_URL: z.string().min(1),
  PUBLIC_URL: z.httpUrl(),
  DEMO_ACCESS_KEY: z.string().min(1),
  PORT: z.string().optional(),
});

export type HttpConfig = {
  publicUrl: string;
  demoAccessKey: string;
  bodyLimitBytes: number;
};

export type AppConfig = HttpConfig & {
  databaseUrl: string;
  port: number;
};

export function loadConfig(env: NodeJS.ProcessEnv = process.env): AppConfig {
  const parsed = EnvSchema.parse(env);
  const port = parsed.PORT === undefined ? DEFAULT_PORT : Number(parsed.PORT);
  if (!Number.isInteger(port) || port <= 0) {
    throw new Error("PORT must be a positive integer");
  }

  return {
    databaseUrl: parsed.DATABASE_URL,
    publicUrl: parsed.PUBLIC_URL,
    demoAccessKey: parsed.DEMO_ACCESS_KEY,
    bodyLimitBytes: CRUD_BODY_LIMIT_BYTES,
    port,
  };
}

import type { FastifyReply, FastifyRequest } from "fastify";

import { sendApiError } from "../http/errors.js";

export function isWorkflowsPath(url: string): boolean {
  const path = url.split("?")[0] ?? "";
  return path === "/workflows" || path.startsWith("/workflows/");
}

export function createDemoAccessHook(demoAccessKey: string) {
  return async function demoAccessHook(
    request: FastifyRequest,
    reply: FastifyReply,
  ): Promise<void> {
    if (!isWorkflowsPath(request.url)) {
      return;
    }

    const header = request.headers["x-demo-key"];
    const provided = Array.isArray(header) ? header[0] : header;
    if (provided !== demoAccessKey) {
      sendApiError(reply, { error: "unauthorized" });
    }
  };
}

import type { Workflow, WorkflowCreate, WorkflowPatch, WorkflowPut } from "@kisi-workflow/shared";

import { UniqueTriggerTokenError } from "../db/errors.js";
import type { PersistedWorkflow, WorkflowRepository } from "../db/workflow-repository.js";
import { generateTriggerToken, triggerPathFor, triggerUrlFor } from "./trigger-token.js";

const MAX_TOKEN_ATTEMPTS = 8;

export class WorkflowNotFoundError extends Error {
  constructor() {
    super("workflow not found");
    this.name = "WorkflowNotFoundError";
  }
}

export class TriggerTokenAllocationError extends Error {
  constructor() {
    super("failed to allocate a unique trigger token");
    this.name = "TriggerTokenAllocationError";
  }
}

export class WorkflowService {
  constructor(
    private readonly repository: WorkflowRepository,
    private readonly publicUrl: string,
    private readonly generateToken: () => string = generateTriggerToken,
  ) {}

  async list(): Promise<Workflow[]> {
    const rows = await this.repository.list();
    return rows.map((row) => this.toDto(row));
  }

  async getById(id: string): Promise<Workflow> {
    const row = await this.repository.getById(id);
    if (!row) {
      throw new WorkflowNotFoundError();
    }
    return this.toDto(row);
  }

  async create(input: WorkflowCreate): Promise<Workflow> {
    for (let attempt = 0; attempt < MAX_TOKEN_ATTEMPTS; attempt += 1) {
      const triggerToken = this.generateToken();
      try {
        const row = await this.repository.create({
          name: input.name,
          enabled: input.enabled,
          steps: input.steps,
          triggerToken,
          triggerPath: triggerPathFor(triggerToken),
        });
        return this.toDto(row);
      } catch (error) {
        if (error instanceof UniqueTriggerTokenError) {
          continue;
        }
        throw error;
      }
    }

    throw new TriggerTokenAllocationError();
  }

  async patch(id: string, input: WorkflowPatch): Promise<Workflow> {
    const row = await this.repository.update(id, input);
    if (!row) {
      throw new WorkflowNotFoundError();
    }
    return this.toDto(row);
  }

  async put(id: string, input: WorkflowPut): Promise<Workflow> {
    const row = await this.repository.replace(id, input);
    if (!row) {
      throw new WorkflowNotFoundError();
    }
    return this.toDto(row);
  }

  async delete(id: string): Promise<void> {
    const deleted = await this.repository.deleteById(id);
    if (!deleted) {
      throw new WorkflowNotFoundError();
    }
  }

  private toDto(row: PersistedWorkflow): Workflow {
    return {
      ...row,
      triggerUrl: triggerUrlFor(this.publicUrl, row.triggerPath),
    };
  }
}

import {
  WorkflowCreateSchema,
  WorkflowPatchSchema,
  WorkflowPutSchema,
} from "@kisi-workflow/shared";
import type { FastifyPluginAsync } from "fastify";
import { z } from "zod";

import { sendApiError } from "../http/errors.js";
import type { WorkflowService } from "../workflows/service.js";

const WorkflowIdParamsSchema = z.strictObject({
  id: z.uuid(),
});

function validationError(result: { error: { flatten: () => { formErrors: string[]; fieldErrors: Record<string, string[] | undefined> } } }) {
  return {
    error: "validation_error" as const,
    details: result.error.flatten(),
  };
}

export const workflowRoutes: FastifyPluginAsync<{ service: WorkflowService }> = async (
  app,
  opts,
) => {
  const { service } = opts;

  app.get("/", async () => service.list());

  app.post("/", async (request, reply) => {
    const parsed = WorkflowCreateSchema.safeParse(request.body);
    if (!parsed.success) {
      return sendApiError(reply, {
        error: "validation_error",
        details: parsed.error.flatten(),
      });
    }
    const created = await service.create(parsed.data);
    return reply.status(201).send(created);
  });

  app.get("/:id", async (request, reply) => {
    const params = WorkflowIdParamsSchema.safeParse(request.params);
    if (!params.success) {
      return sendApiError(reply, {
        error: "validation_error",
        details: params.error.flatten(),
      });
    }
    return service.getById(params.data.id);
  });

  app.patch("/:id", async (request, reply) => {
    const params = WorkflowIdParamsSchema.safeParse(request.params);
    if (!params.success) {
      return sendApiError(reply, {
        error: "validation_error",
        details: params.error.flatten(),
      });
    }
    const parsed = WorkflowPatchSchema.safeParse(request.body);
    if (!parsed.success) {
      return sendApiError(reply, {
        error: "validation_error",
        details: parsed.error.flatten(),
      });
    }
    return service.patch(params.data.id, parsed.data);
  });

  app.put("/:id", async (request, reply) => {
    const params = WorkflowIdParamsSchema.safeParse(request.params);
    if (!params.success) {
      return sendApiError(reply, {
        error: "validation_error",
        details: params.error.flatten(),
      });
    }
    const parsed = WorkflowPutSchema.safeParse(request.body);
    if (!parsed.success) {
      return sendApiError(reply, {
        error: "validation_error",
        details: parsed.error.flatten(),
      });
    }
    return service.put(params.data.id, parsed.data);
  });

  app.delete("/:id", async (request, reply) => {
    const params = WorkflowIdParamsSchema.safeParse(request.params);
    if (!params.success) {
      return sendApiError(reply, {
        error: "validation_error",
        details: params.error.flatten(),
      });
    }
    await service.delete(params.data.id);
    return reply.status(204).send();
  });
};

import Fastify, { type FastifyError, type FastifyInstance } from "fastify";

import { createDemoAccessHook } from "./auth/demo-access.js";
import type { HttpConfig } from "./config.js";
import type { WorkflowRepository } from "./db/workflow-repository.js";
import { sendApiError } from "./http/errors.js";
import { workflowRoutes } from "./routes/workflows.js";
import { WorkflowNotFoundError, WorkflowService } from "./workflows/service.js";
import { generateTriggerToken } from "./workflows/trigger-token.js";

export type BuildAppOptions = {
  repository: WorkflowRepository;
  config: HttpConfig;
  generateTriggerToken?: () => string;
  logger?: boolean;
};

function isBodyTooLarge(error: FastifyError): boolean {
  return error.statusCode === 413 || error.code === "FST_ERR_CTP_BODY_TOO_LARGE";
}

export async function buildApp(options: BuildAppOptions): Promise<FastifyInstance> {
  const app = Fastify({
    logger: options.logger ?? false,
    bodyLimit: options.config.bodyLimitBytes,
  });

  const service = new WorkflowService(
    options.repository,
    options.config.publicUrl,
    options.generateTriggerToken ?? generateTriggerToken,
  );

  app.addHook("onRequest", createDemoAccessHook(options.config.demoAccessKey));

  app.setNotFoundHandler((_request, reply) => {
    return sendApiError(reply, { error: "not_found" });
  });

  app.setErrorHandler((error: FastifyError, _request, reply) => {
    if (error instanceof WorkflowNotFoundError) {
      return sendApiError(reply, { error: "not_found" });
    }
    if (isBodyTooLarge(error)) {
      return sendApiError(reply, { error: "payload_too_large" });
    }
    if (error.statusCode === 400) {
      return sendApiError(reply, {
        error: "validation_error",
        details: {
          formErrors: [error.message],
          fieldErrors: {},
        },
      });
    }

    requestLogError(app, error);
    return sendApiError(reply, { error: "internal_error" });
  });

  await app.register(workflowRoutes, { prefix: "/workflows", service });
  return app;
}

function requestLogError(app: FastifyInstance, error: FastifyError): void {
  app.log.error(error);
}

